// ponytail: Intl only; swap for Temporal.ZonedDateTime once Node and Safari ship it
const cache = new Map<string, Intl.DateTimeFormat>();
function fmt(locale: string, timeZone: string, opts: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${timeZone}|${JSON.stringify(opts)}`;
  let f = cache.get(key);
  if (!f) { f = new Intl.DateTimeFormat(locale, { ...opts, timeZone }); cache.set(key, f); }
  return f;
}
const part = (parts: Intl.DateTimeFormatPart[], type: string) => parts.find((p) => p.type === type)?.value ?? '';

export function isValidTimeZone(tz: string): boolean {
  if (tz !== 'UTC' && !tz.includes('/')) return false;
  try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return true; } catch { return false; }
}
export function offsetMinutes(at: Date, tz: string): number {
  const name = part(fmt('en-US', tz, { timeZoneName: 'longOffset' }).formatToParts(at), 'timeZoneName');
  const m = /^GMT([+-])(\d{2}):(\d{2})$/.exec(name);
  if (!m) return 0;
  return (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3]));
}
export function localDate(at: Date, tz: string): string {
  const p = fmt('en-US', tz, { year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(at);
  return `${part(p, 'year')}-${part(p, 'month')}-${part(p, 'day')}`;
}
const parseDate = (date: string) => date.split('-').map(Number) as [number, number, number];
export function weekdayOf(date: string): number { const [y, m, d] = parseDate(date); return new Date(Date.UTC(y, m - 1, d)).getUTCDay(); }
export function addDays(date: string, days: number): string { const [y, m, d] = parseDate(date); return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10); }
export function zonedTimeToInstant(date: string, time: string, tz: string): Date {
  const [y, m, d] = parseDate(date);
  const [hh = 0, mm = 0, ss = 0] = time.split(':').map(Number);
  const wall = Date.UTC(y, m - 1, d, hh, mm, ss);
  const early = offsetMinutes(new Date(wall - 86_400_000), tz);
  const late = offsetMinutes(new Date(wall + 86_400_000), tz);
  const valid = [early, late].map((o) => wall - o * 60_000).filter((t) => offsetMinutes(new Date(t), tz) * 60_000 === wall - t);
