import { addDays, localDate, weekdayOf, zonedTimeToInstant } from '../shared/time.ts';
export const CLASS_MINUTES = 60, LEAD_MINUTES = 120, HORIZON_DAYS = 14, DAILY_CAP = 2;
export type WorkingHours = { weekday: number; start: string; end: string };
export type Mentor = { id: number; name: string; email: string; bio: string; subjects: string[]; timeZone: string; hours: WorkingHours[] };
export type ActiveBooking = { mentorId: number; startsAt: Date; mentorLocalDate: string };
export type Slot = { startsAt: Date; available: boolean };
const HOUR = 3_600_000, CLASS = CLASS_MINUTES * 60_000;
export function isBookableTime(startsAt: Date, now: Date): boolean {
  const t = startsAt.getTime();
  return t % HOUR === 0 && t >= now.getTime() + LEAD_MINUTES * 60_000 && t <= now.getTime() + HORIZON_DAYS * 86_400_000;
}
function windows(m: Mentor, date: string): [number, number][] {
  return m.hours.filter((h) => h.weekday === weekdayOf(date)).map((h) => [zonedTimeToInstant(date, h.start, m.timeZone).getTime(), zonedTimeToInstant(date, h.end, m.timeZone).getTime()]);
}
export function worksAt(m: Mentor, startsAt: Date): boolean {
  const t = startsAt.getTime();
  return windows(m, localDate(startsAt, m.timeZone)).some(([s, e]) => t >= s && t + CLASS <= e);
}
export function classStarts(m: Mentor, from: Date, to: Date): Date[] {
  const out = new Set<number>();
  const last = addDays(localDate(to, m.timeZone), 1);
  for (let d = addDays(localDate(from, m.timeZone), -1); d <= last; d = addDays(d, 1))
    for (const [s, e] of windows(m, d))
      for (let t = Math.ceil(s / HOUR) * HOUR; t + CLASS <= e; t += HOUR)
        if (t >= from.getTime() && t <= to.getTime()) out.add(t);
  return [...out].sort((a, b) => a - b).map((t) => new Date(t));
}
export function buildSlots(mentors: Mentor[], bookings: ActiveBooking[], now: Date): Slot[] {
  const from = new Date(now.getTime() + LEAD_MINUTES * 60_000), to = new Date(now.getTime() + HORIZON_DAYS * 86_400_000);
  const booked = new Set(bookings.map((b) => `${b.mentorId}|${b.startsAt.getTime()}`));
  const counts = new Map<string, number>();
  for (const b of bookings) counts.set(`${b.mentorId}|${b.mentorLocalDate}`, (counts.get(`${b.mentorId}|${b.mentorLocalDate}`) ?? 0) + 1);
  const byInstant = new Map<number, boolean>();
  for (const m of mentors) for (const s of classStarts(m, from, to)) {
    const t = s.getTime();
    const open = !booked.has(`${m.id}|${t}`) && (counts.get(`${m.id}|${localDate(s, m.timeZone)}`) ?? 0) < DAILY_CAP;
    byInstant.set(t, (byInstant.get(t) ?? false) || open);
  }
  return [...byInstant].sort((a, b) => a[0] - b[0]).map(([t, available]) => ({ startsAt: new Date(t), available }));
}
