import { DAILY_CAP, isBookableTime, worksAt, type ActiveBooking, type Mentor } from './slots.ts';
export type BookingInput = { startsAt: Date; parentName: string; parentEmail: string; childName: string; parentTimeZone: string };
export type Booking = BookingInput & { id: string; mentorId: number; mentorLocalDate: string; classLink: string; cancelledAt: Date | null };
export type BookResult = { ok: true; booking: Booking } | { ok: false; code: 'SLOT_UNAVAILABLE' };
export function newClassLink(): string { return `https://classroom.example/trial/${randomUUID()}`; }
export async function loadMentors(pool: Pool): Promise<Mentor[]> {
  const ms = (await pool.query('select * from mentors order by id')).rows;
  const hs = (await pool.query('select * from mentor_hours order by mentor_id, weekday, start_time')).rows;
  return ms.map((m) => ({ id: m.id, name: m.name, email: m.email, bio: m.bio, subjects: m.subjects, timeZone: m.time_zone,
    hours: hs.filter((h) => h.mentor_id === m.id).map((h) => ({ weekday: h.weekday, start: h.start_time.slice(0, 5), end: h.end_time.slice(0, 5) })) }));
}
export async function loadActiveBookings(pool: Pool, from: Date, to: Date): Promise<ActiveBooking[]> {
  const { rows } = await pool.query('select mentor_id, starts_at, mentor_local_date from bookings where cancelled_at is null and starts_at >= $1 and starts_at < $2', [from, to]);
  return rows.map((r) => ({ mentorId: r.mentor_id, startsAt: r.starts_at, mentorLocalDate: r.mentor_local_date }));
}
const toBooking = (r: any): Booking => ({ id: r.id, mentorId: r.mentor_id, startsAt: r.starts_at, mentorLocalDate: r.mentor_local_date, parentName: r.parent_name,
  parentEmail: r.parent_email, childName: r.child_name, parentTimeZone: r.parent_time_zone, classLink: r.class_link, cancelledAt: r.cancelled_at });
export async function bookSlot(pool: Pool, input: BookingInput, now: Date, hooks?: { beforeInsert?: () => Promise<void> }): Promise<BookResult> {
  if (!isBookableTime(input.startsAt, now)) return { ok: false, code: 'SLOT_UNAVAILABLE' };
  const mentors = (await loadMentors(pool)).filter((m) => worksAt(m, input.startsAt));
  const days = mentors.map((m) => localDate(input.startsAt, m.timeZone));
  const { rows } = await pool.query('select mentor_id, mentor_local_date, count(*)::int as n from bookings where cancelled_at is null and mentor_local_date = any($1::date[]) group by mentor_id, mentor_local_date', [days]);
  const count = (m: Mentor) => rows.find((r) => r.mentor_id === m.id && r.mentor_local_date === localDate(input.startsAt, m.timeZone))?.n ?? 0;
  mentors.sort((a, b) => count(a) - count(b) || a.id - b.id);
  for (const m of mentors) {
    const day = localDate(input.startsAt, m.timeZone);
    const client = await pool.connect();
    try {
      await client.query('begin');
      // the turnstile: bookings for one mentor take turns (spec §6); relies on read committed
      if (!process.env.NO_LOCK) await client.query('select id from mentors where id = $1 for update', [m.id]);
      const taken = await client.query('select 1 from bookings where mentor_id = $1 and starts_at = $2 and cancelled_at is null', [m.id, input.startsAt]);
      if (taken.rowCount) { await client.query('rollback'); continue; }
      const c = await client.query('select count(*)::int as n from bookings where mentor_id = $1 and mentor_local_date = $2 and cancelled_at is null', [m.id, day]);
      if (c.rows[0].n >= DAILY_CAP) { await client.query('rollback'); continue; }
      await hooks?.beforeInsert?.();
      const ins = await client.query(`insert into bookings (mentor_id, starts_at, mentor_local_date, parent_name, parent_email, child_name, parent_time_zone, class_link)
        values ($1,$2,$3,$4,$5,$6,$7,$8) returning *`, [m.id, input.startsAt, day, input.parentName, input.parentEmail, input.childName, input.parentTimeZone, newClassLink()]);
      await client.query('commit');
      return { ok: true, booking: toBooking(ins.rows[0]) };
    } catch (e: any) {
      await client.query('rollback');
      if (e.code === '23505') continue;
      throw e;
    } finally { client.release(); }
  }
  return { ok: false, code: 'SLOT_UNAVAILABLE' };
}
export async function getBookingWithMentor(pool: Pool, id: string): Promise<{ booking: Booking; mentor: Mentor } | null> {
  const { rows } = await pool.query('select * from bookings where id = $1', [id]);
  if (!rows[0]) return null;
  const booking = toBooking(rows[0]);
  const mentor = (await loadMentors(pool)).find((m) => m.id === booking.mentorId)!;
  return { booking, mentor };
}
