import express, { type Express, type NextFunction, type Request, type Response } from 'express';
import type { Pool } from 'pg';
import { z } from 'zod';
import { isValidTimeZone } from '../shared/time.ts';
import type { ApiErrorBody, BookingDto, ErrorCode } from '../shared/types.ts';
import { bookSlot, getBookingWithMentor, loadActiveBookings, loadMentors } from './bookings.ts';
import { renderEmails, type Mailer } from './email.ts';
import { buildSlots } from './slots.ts';
export type Clock = { now: () => Date; demo: boolean };
export function createClock(demoNow: string | undefined, realNow: () => number = Date.now): Clock {
  if (!demoNow) return { now: () => new Date(realNow()), demo: false };
  const at = Date.parse(demoNow);
  if (Number.isNaN(at)) throw new Error('DEMO_NOW must be an ISO instant');
  const offset = at - realNow();
  return { now: () => new Date(realNow() + offset), demo: true };
}
const name = z.string().trim().min(1).max(80).regex(/^[^\p{Cc}]*$/u);
const Body = z.object({
  startsAt: z.iso.datetime({ offset: true }).transform((s) => new Date(s)).refine((d) => d.getTime() % 3_600_000 === 0, 'Must be on the hour'),
  parentName: name, childName: name, parentEmail: z.email().max(254), parentTimeZone: z.string().max(64).refine(isValidTimeZone),
});
const err = (res: Response, status: number, code: ErrorCode, message: string, fields?: Record<string, string>) =>
  res.status(status).json({ error: { code, message, ...(fields && { fields }) } } satisfies ApiErrorBody);
const DAY = 86_400_000;
export function createApp(deps: { pool: Pool; clock: Clock; mailer: Mailer; appUrl: string; webDir?: string; log?: (message: string, error?: unknown) => void }): Express {
  const { pool, clock, mailer, appUrl, webDir, log = console.error } = deps;
  const app = express();
  app.disable('x-powered-by');
  app.use('/api', (_req, res, next) => { res.set('Cache-Control', 'no-store'); next(); });
  app.use(express.json());
  app.get('/api/slots', async (_req, res) => {
    const now = clock.now();
    const slots = buildSlots(await loadMentors(pool), await loadActiveBookings(pool, new Date(now.getTime() - 2 * DAY), new Date(now.getTime() + 16 * DAY)), now);
    res.json({ now: now.toISOString(), demo: clock.demo, slots: slots.map((s) => ({ startsAt: s.startsAt.toISOString(), available: s.available })) });
  });
  const dto = async (id: string): Promise<BookingDto | null> => {
    const r = await getBookingWithMentor(pool, id);
    if (!r) return null;
    const { booking: b, mentor: m } = r;
    return { id: b.id, startsAt: b.startsAt.toISOString(), endsAt: new Date(b.startsAt.getTime() + 3_600_000).toISOString(), childName: b.childName, parentName: b.parentName,
