  };
  app.post('/api/bookings', async (req, res) => {
    const input = Body.parse(req.body);
    const result = await bookSlot(pool, input, clock.now());
    if (!result.ok) return void err(res, 409, 'SLOT_UNAVAILABLE', 'That time is no longer available.');
    const r = (await getBookingWithMentor(pool, result.booking.id))!;
    res.status(201).json({ booking: await dto(result.booking.id) });
    const { parent, mentor } = renderEmails({ ...result.booking, mentor: r.mentor }, appUrl);
    for (const s of await Promise.allSettled([mailer.send(parent), mailer.send(mentor)])) if (s.status === 'rejected') log('email failed', s.reason);
  });
  app.get('/api/bookings/:id', async (req, res) => {
    const id = z.uuid().safeParse(req.params.id);
    const b = id.success ? await dto(id.data) : null;
    if (!b) return void err(res, 404, 'NOT_FOUND', 'Booking not found.');
    res.json({ booking: b });
  });
  app.get('/api/mentors', async (_req, res) => {
    const now = clock.now();
    const bookings = await loadActiveBookings(pool, now, new Date(now.getTime() + 30 * DAY));
    res.json({ now: now.toISOString(), demo: clock.demo, mentors: (await loadMentors(pool)).map((m) => ({ id: m.id, name: m.name, bio: m.bio, subjects: m.subjects, timeZone: m.timeZone,
      bookings: bookings.filter((b) => b.mentorId === m.id).map((b) => ({ startsAt: b.startsAt.toISOString() })) })) });
  });
  app.use('/api', (_req, res) => void err(res, 404, 'NOT_FOUND', 'Not found.'));
  if (webDir) {
    app.use(express.static(webDir));
    app.get('/{*splat}', (_req, res) => res.sendFile('index.html', { root: webDir }));
  }
  app.use((e: any, _req: Request, res: Response, _next: NextFunction) => {
    if (e instanceof z.ZodError) {
      const fields: Record<string, string> = {};
      for (const i of e.issues) fields[i.path.join('.')] ??= i.message;
      return void err(res, 400, 'VALIDATION_FAILED', 'Please check the highlighted fields.', fields);
    }
    if (e?.type === 'entity.parse.failed') return void err(res, 400, 'VALIDATION_FAILED', 'The request body is not valid JSON.');
    log('unhandled error', e);
    err(res, 500, 'INTERNAL', 'Something went wrong.');
  });
  return app;
}
