import { addDays, canonicalTimeZone, formatZoneOption, isValidTimeZone, localDate, offsetMinutes, zonedTimeToInstant, zoneAbbreviation } from '../shared/time.ts';
import type { SlotDto } from '../shared/types.ts';
export const DAYS_SHOWN = 14;
export const COMMON_ZONES = ['America/Los_Angeles', 'America/Denver', 'America/Phoenix', 'America/Chicago', 'America/New_York',
  'America/Anchorage', 'Pacific/Honolulu', 'Europe/London', 'Europe/Dublin', 'Asia/Kolkata'];
export type Day = { key: string; slots: SlotDto[]; openCount: number };
export function groupIntoDays(slots: SlotDto[], tz: string, now: Date): Day[] {
  const today = localDate(now, tz);
  const days: Day[] = Array.from({ length: DAYS_SHOWN }, (_, i) => ({ key: addDays(today, i), slots: [], openCount: 0 }));
  for (const s of slots) { const d = days.find((x) => x.key === localDate(new Date(s.startsAt), tz)); if (d) { d.slots.push(s); if (s.available) d.openCount++; } }
  return days;
}
export function shownDayKey(days: Day[], selected: string | null, chosenDay: string | null, tz: string): string {
  const has = (k: string | null) => k !== null && days.some((d) => d.key === k);
  const sel = selected ? localDate(new Date(selected), tz) : null;
  if (has(sel)) return sel!;
  if (has(chosenDay)) return chosenDay!;
  return (days.find((d) => d.openCount > 0) ?? days[0])!.key;
}
export function nearestOpenTimes(slots: SlotDto[], target: string, count = 3): string[] {
  const t = Date.parse(target);
  return slots.filter((s) => s.available && s.startsAt !== target).map((s) => s.startsAt)
    .sort((a, b) => Math.abs(Date.parse(a) - t) - Math.abs(Date.parse(b) - t) || Date.parse(a) - Date.parse(b)).slice(0, count).sort((a, b) => Date.parse(a) - Date.parse(b));
}
export function nearestOpenDays(days: Day[], key: string): { before: Day | null; after: Day | null } {
  const i = days.findIndex((d) => d.key === key);
  return { before: days.slice(0, i).reverse().find((d) => d.openCount > 0) ?? null, after: days.slice(i + 1).find((d) => d.openCount > 0) ?? null };
}
export function clockChange(days: Day[], tz: string, now: Date): { dayKey: string; from: string; to: string } | null {
  const o = offsetMinutes(now, tz);
  for (const d of days) { const noon = zonedTimeToInstant(d.key, '12:00', tz); if (offsetMinutes(noon, tz) !== o) return { dayKey: d.key, from: zoneAbbreviation(now, tz), to: zoneAbbreviation(noon, tz) }; }
  return null;
}
export function dayMixesOffsets(day: Day, tz: string): boolean { return new Set(day.slots.map((s) => offsetMinutes(new Date(s.startsAt), tz))).size > 1; }
export function zoneOptions(current: string, now: Date): { value: string; label: string; group: 'common' | 'all' }[] {
  const seen = new Set<string>(); const out: { value: string; label: string; group: 'common' | 'all' }[] = [];
  const cur = canonicalTimeZone(current); let matched = false;
  const add = (tz: string, group: 'common' | 'all') => { const c = canonicalTimeZone(tz); if (seen.has(c)) return; seen.add(c); const value = c === cur ? (matched = true, current) : tz; out.push({ value, label: formatZoneOption(now, value), group }); };
  COMMON_ZONES.forEach((z) => add(z, 'common')); Intl.supportedValuesOf('timeZone').forEach((z) => add(z, 'all'));
  if (!matched) out.unshift({ value: current, label: formatZoneOption(now, current), group: 'common' });
  return out;
}
export function initialTimeZone(stored: string | null, device: string): string { return stored && isValidTimeZone(stored) ? stored : device; }
